"use strict";(globalThis.webpackChunkelemental_selenium||=[]).push([[53305],{292892(e){e.exports=JSON.parse('{"tag":{"label":"test setup","permalink":"/tips/tags/test-setup","allTagsPath":"/tips/tags","count":2,"items":[{"id":"rest-apis/24-rest-apis","title":"Fast and Reliable Test Setup with REST APIs","description":"Signing up and logging in through the UI makes every test slower and more fragile. When the application has an API, the test can create its user with one HTTP call, log in with a session cookie, and keep the browser for what it needs to check.","permalink":"/tips/24-rest-apis"},{"id":"reuse-a-login/70-reuse-a-login","title":"How to Reuse a Login Across Tests","description":"Logging in through the form at the start of every test makes the suite slow, and every test fails when the login page has a problem. The test suite can log in once, keep the session cookie, and start each test already logged in.","permalink":"/tips/70-reuse-a-login"}],"unlisted":false}}')}}]);